import{_ as a,o as s,c as e,ai as n}from"./chunks/framework.iNbpOH0p.js";const g=JSON.parse('{"title":"浏览器 答案","description":"","frontmatter":{},"headers":[],"relativePath":"doc/2.Interview/2.Answer/Answer-9/18-Browser.md","filePath":"doc/2.Interview/2.Answer/Answer-9/18-Browser.md"}'),r={name:"doc/2.Interview/2.Answer/Answer-9/18-Browser.md"};function d(o,t,i,l,h,p){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="浏览器-答案" tabindex="-1">浏览器 答案 <a class="header-anchor" href="#浏览器-答案" aria-label="Permalink to “浏览器 答案”">​</a></h1><h2 id="一、浏览器架构" tabindex="-1">一、浏览器架构 <a class="header-anchor" href="#一、浏览器架构" aria-label="Permalink to “一、浏览器架构”">​</a></h2><p>现代浏览器（Chrome）采用<strong>多进程架构</strong>：</p><table tabindex="0"><thead><tr><th>进程</th><th>职责</th></tr></thead><tbody><tr><td><strong>浏览器主进程</strong></td><td>UI、地址栏、书签、网络请求</td></tr><tr><td><strong>渲染进程</strong></td><td>解析 HTML/CSS/JS → 渲染页面（每个标签页一个）</td></tr><tr><td><strong>GPU 进程</strong></td><td>加速渲染</td></tr><tr><td><strong>插件进程</strong></td><td>隔离插件</td></tr><tr><td><strong>网络进程</strong></td><td>网络资源加载</td></tr></tbody></table><blockquote><p>多进程隔离：一个标签页崩溃不影响其他标签页。</p></blockquote><hr><h2 id="二、渲染流程" tabindex="-1">二、渲染流程 <a class="header-anchor" href="#二、渲染流程" aria-label="Permalink to “二、渲染流程”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTML → HTML Parser → DOM Tree</span></span>
<span class="line"><span>CSS  → CSS Parser  → CSSOM Tree</span></span>
<span class="line"><span>         ↘        ↙</span></span>
<span class="line"><span>        Render Tree</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Layout（回流）→ 计算几何信息</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Paint（分层）</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Composite（合成层）→ GPU 显示</span></span></code></pre></div><hr><h2 id="三、重绘与回流" tabindex="-1">三、重绘与回流 <a class="header-anchor" href="#三、重绘与回流" aria-label="Permalink to “三、重绘与回流”">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>触发条件</th><th>开销</th></tr></thead><tbody><tr><td><strong>回流/重排</strong></td><td>几何属性（尺寸、位置）改变</td><td><strong>大</strong></td></tr><tr><td><strong>重绘</strong></td><td>外观属性（颜色、背景）改变</td><td>小</td></tr><tr><td><strong>合成</strong></td><td>transform/opacity 改变</td><td><strong>无</strong></td></tr></tbody></table><ul><li>回流必然触发重绘，重绘不一定回流</li><li><code>transform</code>, <code>opacity</code> 只走合成，不触发回流/重绘 — 动画首选</li></ul><hr><h2 id="四、事件循环-event-loop" tabindex="-1">四、事件循环（Event Loop） <a class="header-anchor" href="#四、事件循环-event-loop" aria-label="Permalink to “四、事件循环（Event Loop）”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>同步代码全部执行完</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>清空微任务队列（Promise.then, MutationObserver）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>执行一个宏任务（setTimeout, I/O, UI 渲染）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>再次清空微任务 ↓ 循环</span></span></code></pre></div><hr><h2 id="五、垃圾回收-gc" tabindex="-1">五、垃圾回收（GC） <a class="header-anchor" href="#五、垃圾回收-gc" aria-label="Permalink to “五、垃圾回收（GC）”">​</a></h2><p><strong>V8 GC 机制</strong>：</p><table tabindex="0"><thead><tr><th>策略</th><th>对象</th><th>算法</th></tr></thead><tbody><tr><td>新生代</td><td>生命周期短</td><td><strong>Scavenge</strong>(复制，快)</td></tr><tr><td>老生代</td><td>生命周期长</td><td><strong>标记清除 + 标记整理</strong></td></tr></tbody></table><p><strong>标记清除</strong>：从根对象出发标记可达对象，清除不可达的。</p><hr><h2 id="六、浏览器缓存" tabindex="-1">六、浏览器缓存 <a class="header-anchor" href="#六、浏览器缓存" aria-label="Permalink to “六、浏览器缓存”">​</a></h2><table tabindex="0"><thead><tr><th>缓存类型</th><th>字段</th><th>行为</th></tr></thead><tbody><tr><td><strong>强缓存</strong></td><td><code>Cache-Control: max-age=3600</code></td><td>不请求，直接用</td></tr><tr><td><strong>协商缓存</strong></td><td><code>ETag</code> / <code>If-None-Match</code></td><td>请求验证，304 则用缓存</td></tr><tr><td><strong>启发式缓存</strong></td><td>(无明确头)</td><td>浏览器自主判断</td></tr></tbody></table><hr><h2 id="七、存储机制" tabindex="-1">七、存储机制 <a class="header-anchor" href="#七、存储机制" aria-label="Permalink to “七、存储机制”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>容量</th><th>过期</th><th>随请求发送</th></tr></thead><tbody><tr><td>Cookie</td><td>4KB</td><td>可设</td><td>✅ 自动</td></tr><tr><td>localStorage</td><td>5MB+</td><td>永久</td><td>❌</td></tr><tr><td>sessionStorage</td><td>5MB+</td><td>关闭标签</td><td>❌</td></tr><tr><td>IndexedDB</td><td>大</td><td>永久</td><td>❌（异步 NoSQL）</td></tr></tbody></table><hr><h2 id="八、跨域与安全" tabindex="-1">八、跨域与安全 <a class="header-anchor" href="#八、跨域与安全" aria-label="Permalink to “八、跨域与安全”">​</a></h2><p><strong>同源策略</strong>：协议+域名+端口全相同。</p><p><strong>XSS</strong>（跨站脚本攻击）：注入恶意脚本 → 对输入转义、CSP 头</p><p><strong>CSRF</strong>（跨站请求伪造）：伪造用户请求 → Token 校验、SameSite Cookie</p><p><strong>CSP</strong>（内容安全策略）：<code>Content-Security-Policy</code> HTTP 头限制资源来源</p><hr><h2 id="九、性能优化" tabindex="-1">九、性能优化 <a class="header-anchor" href="#九、性能优化" aria-label="Permalink to “九、性能优化”">​</a></h2><table tabindex="0"><thead><tr><th>层面</th><th>策略</th></tr></thead><tbody><tr><td>网络</td><td>CDN、HTTP/2、资源压缩、预加载(preload/prefetch)</td></tr><tr><td>资源</td><td>懒加载、图片 WebP、代码分割</td></tr><tr><td>渲染</td><td>避免回流、虚拟列表、<code>will-change</code>、<code>content-visibility</code></td></tr><tr><td>缓存</td><td>强缓存 + 协商缓存 + Service Worker</td></tr></tbody></table><p><strong>关键指标</strong>：</p><ul><li><strong>FP/FCP</strong>：首次绘制/内容绘制（白屏时间）</li><li><strong>LCP</strong>：最大内容绘制（≤ 2.5s）</li><li><strong>FID/INP</strong>：首次输入延迟 / 交互延迟</li><li><strong>CLS</strong>：累积布局偏移</li></ul>`,37)])])}const b=a(r,[["render",d]]);export{g as __pageData,b as default};
